    """Return whether an exported span may be marked as an application root."""
    if span.parent is None or span.instrumentation_scope is None:
        return True

    return (
        span.instrumentation_scope.name,
        span.name,
    ) not in APP_ROOT_INELIGIBLE_SPANS


def add_app_root_ineligible_span(scope_name: str, span_name: str) -> None:
    """Add a (scope_name, span_name) pair to the set of spans that are not eligible as app roots.

    This allows callers to dynamically extend the default exclusion list.
    """
    APP_ROOT_INELIGIBLE_SPANS.add((scope_name, span_name))"
